import { readFile, writeFile } from 'node:fs/promises';

export async function writePrintAssets(): Promise<void> {
  const css = await readFile(new URL('../web/proens.css', import.meta.url), 'utf8');
  const logo = await readFile(new URL('../web/ifpr-logo.png', import.meta.url));
  await writeFile(
    new URL('../src/native-print-assets.mjs', import.meta.url),
    '// Generated by scripts/print-assets.ts from the print template.\n' +
      'export const printCss = ' +
      JSON.stringify(css) +
      ';\n' +
      'export const printLogo = ' +
      JSON.stringify('data:image/png;base64,' + logo.toString('base64')) +
      ';\n',
  );
}
